package com.nivor.analytics;import com.nivor.analytics.AnalyticsDtos.*;import java.time.LocalDate;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.core.userdetails.UserDetails;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/analytics")public class AnalyticsController{private final AnalyticsService service;public AnalyticsController(AnalyticsService s){service=s;}@GetMapping("/overview")public Overview overview(@AuthenticationPrincipal UserDetails u,@RequestParam(required=false)LocalDate from,@RequestParam(required=false)LocalDate to){return service.overview(u.getUsername(),from,to);}@GetMapping("/productivity")public Overview productivity(@AuthenticationPrincipal UserDetails u,@RequestParam(required=false)LocalDate from,@RequestParam(required=false)LocalDate to){return service.overview(u.getUsername(),from,to);}@GetMapping("/focus")public FocusOverview focus(@AuthenticationPrincipal UserDetails u,@RequestParam(required=false)LocalDate from,@RequestParam(required=false)LocalDate to){return service.focus(u.getUsername(),from,to);}@GetMapping("/habits")public HabitOverview habits(@AuthenticationPrincipal UserDetails u,@RequestParam(required=false)LocalDate from,@RequestParam(required=false)LocalDate to){return service.habit(u.getUsername(),from,to);}@GetMapping("/goals")public GoalOverview goals(@AuthenticationPrincipal UserDetails u){return service.goal(u.getUsername());}}
